74	        this.clinicService = clinicService;
75	        this.ownerMapper = ownerMapper;
76	        this.petMapper = petMapper;
77	        this.visitMapper = visitMapper;
78	    }
79	
80	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
81	    @Override
82	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
83	        Collection<Owner> owners;
84	        if (lastName != null) {
85	            owners = this.clinicService.findOwnerByLastName(lastName);
86	        } else {
87	            owners = this.clinicService.findAllOwners();
88	        }
89	        if (owners.isEmpty()) {
90	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
91	        }
92	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
93	    }
94	
95	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
96	    @Override
97	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
98	        Owner owner = this.clinicService.findOwnerById(ownerId);
99	        if (owner == null) {
100	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
101	        }
102	        owner.setHouseholdSize(this.clinicService.countOwnersByHouseholdId(owner.getHouseholdId()));
103	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
104	        ownerDto.setBulkSignupWarning(isBulkSignup(owner.getRegistrationDate()));
105	        return new ResponseEntity<>(ownerDto, HttpStatus.OK);
106	    }
107	
108	    /**
109	     * Whether more than 80 owners have already been created on {@code registrationDate},
110	     * signalling a bulk-signup surge for the read-only {@code bulkSignupWarning} field.
111	     */
112	    private boolean isBulkSignup(LocalDate registrationDate) {
113	        return this.clinicService.countOwnersByRegistrationDate(registrationDate) > 80;
114	    }
115	
116	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
117	    @Override
118	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
119	        HttpHeaders headers = new HttpHeaders();
120	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
121	        LocalDate registrationDate = owner.resolveRegistrationDate();
122	        if (this.clinicService.countOwnersByRegistrationDate(registrationDate) >= 100) {
123	            return new ResponseEntity<>(HttpStatus.TOO_MANY_REQUESTS);
124	        }
125	        if (this.clinicService.countOwnersByCity(owner.getCity()) >= 50) {
126	            return new ResponseEntity<>(HttpStatus.CONFLICT);
127	        }
128	        // The household id is deterministic: owners that share a (normalized lastName, postcode)
129	        // share it automatically. It feeds the identity key and the household-duplicate rule below.
130	        owner.setHouseholdId(this.clinicService.computeHouseholdId(owner));
131	        boolean sharesHousehold = Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold());
132	        boolean householdExists = this.clinicService.existsOwnerInHousehold(owner.getHouseholdId());
133	        // Household duplicate: another owner already shares this (lastName, postcode). Rejected unless
134	        // the caller declares they share the household ('sharesHousehold' only bypasses this block).
135	        if (householdExists && !sharesHousehold) {
136	            return new ResponseEntity<>(HttpStatus.CONFLICT);
137	        }
138	        // Hard duplicate detection is consolidated into the owner's derived identity key (see
139	        // Owner#getIdentityKey): reject only when the new owner's whole key matches an existing one.
140	        if (this.clinicService.existsOwnerWithIdentityKey(owner.getIdentityKey())) {
141	            return new ResponseEntity<>(HttpStatus.CONFLICT);
142	        }
143	        // Soft-match: shares an existing owner's lastName and postcode with a different telephone,
144	        // flagged 'possibleDuplicate'. A declared household member is not a suspected duplicate, so
145	        // the flag is suppressed when this owner joins an existing household.
146	        Integer possibleDuplicateOf = householdExists ? null
147	            : this.clinicService.findPossibleDuplicateOwnerId(owner);
148	        owner.setPossibleDuplicate(possibleDuplicateOf != null);
149	        owner.setPossibleDuplicateOf(possibleDuplicateOf);
150	        owner.setNamesakeCount(
151	            this.clinicService.countOwnersByName(owner.getFirstName(), owner.getLastName()));
152	        this.clinicService.saveOwner(owner);
153	        owner.setHouseholdSize(this.clinicService.countOwnersByHouseholdId(owner.getHouseholdId()));
154	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
155	        ownerDto.setBulkSignupWarning(isBulkSignup(owner.getRegistrationDate()));
156	        auditLogger.info(
157	            "owner created: id={} customerCode={} registrationDate={} membershipLevel={} membershipNumber={}",
158	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(),
159	            ownerDto.getMembershipLevel(), ownerDto.getMembershipNumber());
160	        headers.setLocation(UriComponentsBuilder.newInstance()
161	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
162	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
163	    }
164	
165	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
166	    @Override
167	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
