178	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
179	        currentOwner.setLastName(ownerFieldsDto.getLastName());
180	        currentOwner.setTelephone(ownerMapper.normalizeTelephone(ownerFieldsDto.getTelephone()));
181	        currentOwner.setEmail(ownerFieldsDto.getEmail());
182	        currentOwner.setPostcode(ownerFieldsDto.getPostcode());
183	        this.clinicService.saveOwner(currentOwner);
